import * as actions from '../tax-action/tax.actions';
import { TaxRecordState } from './tax.state';
import { TaxListResponseModel } from '../tax-model/taxlist.response.model';
import { TaxNewResponse } from '../tax-model/taxnewResponse.model';
export const initialState = new TaxRecordState();
export function reducer(state = initialState, {
  type,
  payload
}) {
  if (!type) {
    return state;
  }

  switch (type) {
    case actions.ActionTypes.DO_TAX_LIST:
      {
        return Object.assign({}, state, {
          listLoading: true,
          listLoaded: false,
          listFailed: false
        });
      }

    case actions.ActionTypes.DO_TAX_LIST_COUNT:
      {
        return Object.assign({}, state, {
          countLoading: true,
          countLoaded: false,
          countFailed: false
        });
      }

    case actions.ActionTypes.DO_TAX_LIST_NEW:
      {
        return Object.assign({}, state, {
          addLoading: true,
          addLoaded: false,
          addFailed: false
        });
      }

    case actions.ActionTypes.DO_TAX_UPDATE:
      {
        return Object.assign({}, state, {
          updateLoading: true,
          updateLoaded: false,
          updateFailed: false
        });
      }

    case actions.ActionTypes.DO_TAX_DELETE:
      {
        return Object.assign({}, state, {
          deleteLoading: true,
          deleteLoaded: false,
          deleteFailed: false
        });
      }

    case actions.ActionTypes.DO_TAX_LIST_SUCCESS:
      {
        const taxList = payload.data.map(_tax => {
          const tempListModel = new TaxListResponseModel(_tax);
          return tempListModel;
        });
        return Object.assign({}, state, {
          taxList: taxList,
          listLoading: false,
          listLoaded: true,
          listFailed: false
        });
      }

    case actions.ActionTypes.DO_TAX_LIST_COUNT_SUCCESS:
      {
        return Object.assign({}, state, {
          taxListCount: payload,
          countLoading: false,
          countLoaded: true,
          countFailed: false
        });
      }

    case actions.ActionTypes.DO_TAX_LIST_NEW_SUCCESS:
      {
        const newTax = new TaxNewResponse(payload.data);
        return Object.assign({}, state, {
          taxNew: payload,
          taxNewdetail: newTax,
          addLoading: false,
          addLoaded: true,
          addFailed: false
        });
      }

    case actions.ActionTypes.DO_TAX_UPDATE_SUCCESS:
      {
        return Object.assign({}, state, {
          taxupdate: payload.user,
          updateLoading: false,
          updateLoaded: true,
          updateFailed: false
        });
      }

    case actions.ActionTypes.DO_TAX_DELETE_SUCCESS:
      {
        return Object.assign({}, state, {
          taxDelete: payload,
          deleteLoading: false,
          deleteLoaded: true,
          deleteFailed: false
        });
      }

    case actions.ActionTypes.DO_TAX_LIST_FAIL:
      {
        return Object.assign({}, state, {
          listLoading: false,
          listLoaded: true,
          listFailed: true
        });
      }

    case actions.ActionTypes.DO_TAX_LIST_NEW_FAIL:
      {
        return Object.assign({}, state, {
          updateLoading: false,
          updateLoaded: true,
          updateFailed: true
        });
      }

    case actions.ActionTypes.DO_TAX_UPDATE_FAIL:
      {
        return Object.assign({}, state, {
          updateLoading: false,
          updateLoaded: true,
          updateFailed: true
        });
      }

    case actions.ActionTypes.DO_TAX_DELETE_FAIL:
      {
        return Object.assign({}, state, {
          deleteLoading: false,
          deleteLoaded: true,
          deleteFailed: true
        });
      }

    case actions.ActionTypes.DO_TAX_LIST_COUNT_FAIL:
      {
        return Object.assign({}, state, {
          countLoading: false,
          countLoaded: true,
          countFailed: true
        });
      }

    default:
      {
        return state;
      }
  }
}
export const getTaxList = state => state.taxList;
export const getTaxListCount = state => state.taxListCount;
export const getTaxNew = state => state.taxNew;
export const getTaxNewdetail = state => state.taxNewdetail;
export const getTaxUpdate = state => state.taxupdate;
export const getTaxDelete = state => state.taxDelete;
export const getTaxListLoading = state => state.listLoading;
export const getTaxListLoaded = state => state.listLoaded;
export const getTaxListFailed = state => state.listFailed;
export const getTaxCountLoading = state => state.countLoading;
export const getTaxCountLoaded = state => state.countLoaded;
export const getTaxCountFailed = state => state.countFailed;
export const getTaxAddLoading = state => state.addLoading;
export const getTaxAddLoaded = state => state.addLoaded;
export const getTaxAddFailed = state => state.addFailed;
export const getTaxUpdateLoading = state => state.updateLoading;
export const getTaxUpdateLoaded = state => state.updateLoaded;
export const getTaxUpdateFailed = state => state.updateFailed;
export const getTaxDeleteLoading = state => state.deleteLoading;
export const getTaxDeleteLoaded = state => state.deleteLoaded;
export const getTaxDeleteFailed = state => state.deleteFailed;
